1	import { CHEST_SLOTS, ENCHANT_MAX_LEVEL, HOTBAR_SLOTS, INVENTORY_SLOTS, MAX_HEARTS, MAX_HUNGER, MAX_STACK_SIZE } from "@/lib/game/config";
2	import { ARMOR_SLOTS, createEmptyArmorEquipment, createEmptySlot, createSlot, ITEM_DEF_BY_ID, maxStackSizeForItem } from "@/lib/game/items";
3	import type {
4	  EffectId,
5	  Enchantment,
6	  EnchantmentId,
7	  EquippedArmor,
8	  SaveData,
9	  SaveDataV1,
10	  SaveDataV2,
11	  SaveDataV3,
12	  SaveDataV4,
13	  SaveDataV5,
14	  SaveDataV6,
15	  SaveDataV7,
16	  SavedContainer,
17	  SavedEffect,
18	  SavedSlot,
19	  InventorySlot
20	} from "@/lib/game/types";
21	import { isGameMode, type GameMode } from "@/lib/game/gameModes";
22	
23	/**
24	 * Migrates a v1 save (40 slots, 10-slot hotbar) to v2 (36 slots, 9-slot
25	 * hotbar): non-empty slots are packed in order, stackable items merge into
26	 * earlier stacks, and anything that still overflows 36 slots is dropped.
27	 */
28	/** Coerces a persisted hotbar index to a finite integer within 0..HOTBAR_SLOTS-1. */
29	function normalizeSelectedSlot(value: number): number {
30	  const index = Number.isFinite(value) ? Math.floor(value) : 0;
31	  return Math.max(0, Math.min(HOTBAR_SLOTS - 1, index));
32	}
33	
34	export function migrateSaveV1toV2(save: SaveDataV1): SaveDataV2 {
35	  const migrated: SaveDataV2 = { ...save, version: 2, selectedSlot: normalizeSelectedSlot(save.selectedSlot) };
36	
37	  if (Array.isArray(save.inventorySlots)) {
38	    const packed: Array<{ id: string | null; count: number; durability?: number }> = [];
39	    for (const saved of save.inventorySlots) {
40	      if (!saved?.id || saved.count <= 0) continue;
41	      // Items without durability stack; merge them into an earlier stack first.
42	      const stackable = ITEM_DEF_BY_ID[saved.id] ? !ITEM_DEF_BY_ID[saved.id].maxDurability : false;
43	      let remaining = saved.count;
44	      if (stackable) {
45	        for (const slot of packed) {
46	          if (slot.id !== saved.id || slot.count >= MAX_STACK_SIZE) continue;
47	          const moved = Math.min(MAX_STACK_SIZE - slot.count, remaining);
48	          slot.count += moved;
49	          remaining -= moved;
50	          if (remaining === 0) break;
51	        }
52	      }
53	      while (remaining > 0 && packed.length < INVENTORY_SLOTS) {
54	        const moved = Math.min(maxStackSizeForItem(saved.id), remaining);
55	        packed.push({ id: saved.id, count: moved, durability: saved.durability });
56	        remaining -= moved;
57	      }
58	    }
59	    migrated.inventorySlots = packed;
60	  }
61	
62	  return migrated;
63	}
64	
65	/**
66	 * Migrates a v2 save to v3 — a pure version bump. The new persisted fields
67	 * (dayClock, hearts, hunger, spawnPoint) are optional, so an older save simply
68	 * loads with the engine's defaults for them.
69	 */
70	export function migrateSaveV2toV3(save: SaveDataV2): SaveDataV3 {
71	  return { ...save, version: 3 };
72	}
73	
74	/**
75	 * Migrates a v3 save to v4 — a pure version bump. `blockEntities` (chest
76	 * contents) is optional, so a pre-chest save simply loads with no containers.
77	 */
78	export function migrateSaveV3toV4(save: SaveDataV3): SaveDataV4 {
79	  return { ...save, version: 4 };
80	}
81	
82	/**
83	 * Migrates a v4 save to v5 — a pure version bump. `lootedChests` is optional,
84	 * so a pre-dungeon save simply loads with no dungeon chests yet looted. (In
85	 * practice the SAVE_KEY bump to v6 discards pre-dungeon saves, but the
86	 * migration keeps the version chain complete and the readers total.)
87	 */
88	export function migrateSaveV4toV5(save: SaveDataV4): SaveDataV5 {
89	  return { ...save, version: 5 };
90	}
91	
92	/**
93	 * Migrates a v5 save to v6 — a pure version bump. `effects` (active status
94	 * effects) is optional, so a pre-effect save simply loads with none active.
95	 */
96	export function migrateSaveV5toV6(save: SaveDataV5): SaveDataV6 {
97	  return { ...save, version: 6 };
98	}
99	
100	/**
101	 * Migrates a v6 save to v7 — a pure version bump. `xp` (and per-slot
102	 * `enchantments`) are optional, so a pre-XP save simply loads with `xp` 0 and no
103	 * enchantments.
104	 */
105	export function migrateSaveV6toV7(save: SaveDataV6): SaveDataV7 {
106	  return { ...save, version: 7 };
107	}
108	
109	/**
110	 * Migrates a v7 save to v8 — a pure version bump. `gameMode` is optional, so a
111	 * pre-mode save simply loads as "survival" (see restoreGameMode).
112	 */
113	export function migrateSaveV7toV8(save: SaveDataV7): SaveData {
114	  return { ...save, version: 8 };
115	}
116	
117	// Storage is injectable so save logic can be tested without a browser.
118	export function readSave(saveKey: string, storage: Storage = localStorage): SaveData | null {
119	  try {
120	    const raw = storage.getItem(saveKey);
121	    if (!raw) return null;
122	    const parsed = JSON.parse(raw) as SaveData | SaveDataV7 | SaveDataV6 | SaveDataV5 | SaveDataV4 | SaveDataV3 | SaveDataV2 | SaveDataV1;
123	    if (!parsed || !Number.isFinite(parsed.seed) || !Array.isArray(parsed.changes)) return null;
124	    let migrated: SaveDataV2 | SaveDataV3 | SaveDataV4 | SaveDataV5 | SaveDataV6 | SaveDataV7 | SaveData =
125	      parsed.version === 1 ? migrateSaveV1toV2(parsed) : parsed;
126	    if (migrated.version === 2) migrated = migrateSaveV2toV3(migrated);
127	    if (migrated.version === 3) migrated = migrateSaveV3toV4(migrated);
128	    if (migrated.version === 4) migrated = migrateSaveV4toV5(migrated);
129	    if (migrated.version === 5) migrated = migrateSaveV5toV6(migrated);
130	    if (migrated.version === 6) migrated = migrateSaveV6toV7(migrated);
131	    if (migrated.version === 7) migrated = migrateSaveV7toV8(migrated);
132	    if (migrated.version !== 8) return null;
133	    return migrated;
134	  } catch {
135	    return null;
136	  }
137	}
138	
139	export function writeSave(saveKey: string, data: SaveData, storage: Storage = localStorage): void {
140	  storage.setItem(saveKey, JSON.stringify(data));
141	}
142	
143	export function inventorySlotsSnapshot(inventory: InventorySlot[]): SavedSlot[] {
144	  return inventory.map((slot) => ({ id: slot.id, count: slot.count, durability: slot.durability, enchantments: slot.enchantments }));
145	}
146	
147	// Every known enchantment id, keyed so a new enchantment can't be forgotten here.
148	const VALID_ENCHANT_IDS: Record<EnchantmentId, true> = {
149	  sharpness: true,
150	  protection: true,
151	  efficiency: true,
152	  unbreaking: true
153	};
154	
155	/** Validates persisted enchantments: known ids and integer levels clamped to 1..max; undefined when none survive. */
156	function restoreEnchantments(saved: SavedSlot["enchantments"]): Enchantment[] | undefined {
157	  if (!Array.isArray(saved)) return undefined;
158	  const out: Enchantment[] = [];
159	  for (const entry of saved) {
160	    if (!entry || typeof entry.id !== "string" || !Object.hasOwn(VALID_ENCHANT_IDS, entry.id)) continue;
161	    if (!Number.isFinite(entry.level) || Math.floor(entry.level) < 1) continue;
162	    out.push({ id: entry.id, level: Math.min(ENCHANT_MAX_LEVEL, Math.floor(entry.level)) });
163	  }
164	  return out.length > 0 ? out : undefined;
165	}
166	
167	/**
168	 * Rebuilds one slot from its saved snapshot: drops unknown ids, clamps the
169	 * count, and clamps/defaults durability for gear (a non-positive saved
170	 * durability means the piece broke and is dropped). Returns an empty slot for
171	 * anything invalid. Shared by inventory and container restore.
172	 */
173	function restoreSlot(saved: SavedSlot | undefined): InventorySlot {
174	  if (!saved?.id || saved.count <= 0 || !ITEM_DEF_BY_ID[saved.id]) return createEmptySlot();
175	  const slot = createSlot(saved.id, Math.min(maxStackSizeForItem(saved.id), Math.max(0, Math.floor(saved.count))));
176	  if ((slot.kind === "tool" || slot.kind === "weapon" || slot.kind === "armor") && slot.maxDurability) {
177	    if (typeof saved.durability === "number") {
178	      const loaded = Math.floor(saved.durability);
179	      if (loaded <= 0) return createEmptySlot();
180	      slot.durability = Math.max(1, Math.min(slot.maxDurability, loaded));
181	    } else {
182	      slot.durability = slot.maxDurability;
183	    }
184	    // Enchantments live only on durable gear; validated against the known set.
185	    const enchantments = restoreEnchantments(saved.enchantments);
186	    if (enchantments) slot.enchantments = enchantments;
187	  }
188	  return slot;
189	}
190	
191	/** Snapshots non-empty chest containers for persistence (empty chests carry no data). */
192	export function serializeContainers(containers: Map<number, InventorySlot[]>): SavedContainer[] {
193	  const out: SavedContainer[] = [];
194	  for (const [index, slots] of containers) {
195	    if (!slots.some((slot) => slot.id && slot.count > 0)) continue;
196	    out.push({ index, slots: inventorySlotsSnapshot(slots) });
197	  }
198	  return out;
199	}
200	
201	/** Snapshots the set of opened/broken dungeon chest voxel indices for persistence. */
202	export function serializeLootedChests(looted: Set<number>): number[] {
203	  return [...looted];
204	}
205	
206	/** Reads the opened/broken dungeon chest indices from a save (finite numbers only). */
207	export function readLootedChests(save: SaveData): number[] {
208	  if (!Array.isArray(save.lootedChests)) return [];
209	  return save.lootedChests.filter((value) => Number.isFinite(value));
210	}
211	
212	// Every known status-effect id, as a Record keyed by EffectId so adding an
213	// effect without listing it here is a compile error (keeps the reader total).
214	const VALID_EFFECT_IDS: Record<EffectId, true> = {
215	  speed: true,
216	  strength: true,
217	  regeneration: true,
218	  fire_resistance: true,
219	  water_breathing: true,
220	  poison: true
221	};
222	
223	/** Snapshots the active status effects (id + remaining seconds) for persistence. */
224	export function serializeEffects(effects: Map<EffectId, number>): SavedEffect[] {
225	  const out: SavedEffect[] = [];
226	  for (const [id, remaining] of effects) {
227	    if (remaining > 0) out.push({ id, remaining });
228	  }
229	  return out;
230	}
231	
232	/** Reads active effects from a save, dropping unknown ids and non-positive/garbage durations. */
233	export function restoreEffects(save: SaveData): SavedEffect[] {
234	  if (!Array.isArray(save.effects)) return [];
235	  const out: SavedEffect[] = [];
236	  for (const entry of save.effects) {
237	    if (!entry || typeof entry.id !== "string" || !Object.hasOwn(VALID_EFFECT_IDS, entry.id)) continue;
238	    if (!Number.isFinite(entry.remaining) || entry.remaining <= 0) continue;
239	    out.push({ id: entry.id, remaining: entry.remaining });
240	  }
241	  return out;
242	}
243	
244	/**
245	 * Reads chest containers from a save into validated, CHEST_SLOTS-length slot
246	 * arrays keyed by voxel index. Per-slot validation only — the engine still
247	 * confirms each index actually holds a Chest block before using it.
248	 */
249	export function readContainers(save: SaveData): Array<{ index: number; slots: InventorySlot[] }> {
250	  if (!Array.isArray(save.blockEntities)) return [];
251	  const out: Array<{ index: number; slots: InventorySlot[] }> = [];
252	  for (const entry of save.blockEntities) {
253	    if (!entry || !Number.isFinite(entry.index) || !Array.isArray(entry.slots)) continue;
254	    const slots = Array.from({ length: CHEST_SLOTS }, (_, i) => restoreSlot(entry.slots[i]));
255	    out.push({ index: entry.index, slots });
256	  }
257	  return out;
258	}
259	
260	/**
261	 * Rebuilds inventory slots from a save, dropping unknown items, clamping
262	 * counts and durability, and skipping broken gear. Supports both the current
263	 * inventorySlots shape and the legacy inventoryCounts shape. Returns null when
264	 * the save carries no inventory.
265	 */
266	export function restoreInventorySlots(save: SaveData): InventorySlot[] | null {
267	  if (Array.isArray(save.inventorySlots)) {
268	    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
269	    for (let i = 0; i < Math.min(INVENTORY_SLOTS, save.inventorySlots.length); i += 1) {
270	      slots[i] = restoreSlot(save.inventorySlots[i]);
271	    }
272	    return slots;
273	  }
274	
275	  if (save.inventoryCounts) {
276	    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
277	    let cursor = 0;
278	    for (const [id, raw] of Object.entries(save.inventoryCounts)) {
279	      if (!ITEM_DEF_BY_ID[id]) continue;
280	      let remaining = Math.max(0, Math.floor(raw));
281	      while (remaining > 0 && cursor < slots.length) {
282	        const add = Math.min(maxStackSizeForItem(id), remaining);
283	        slots[cursor] = createSlot(id, add);
284	        cursor += 1;
285	        remaining -= add;
286	      }
287	    }
288	    return slots;
289	  }
290	
291	  return null;
292	}
293	
294	/** Restores equipped armor from a save, ignoring ids that are not valid armor for the slot. */
295	export function restoreEquippedArmor(save: SaveData): EquippedArmor | null {
296	  if (!save.equippedArmor) return null;
297	  const next = createEmptyArmorEquipment();
298	  for (const armorSlot of ARMOR_SLOTS) {
299	    const equippedId = save.equippedArmor[armorSlot];
300	    if (!equippedId) continue;
301	    const def = ITEM_DEF_BY_ID[equippedId];
302	    if (def?.kind !== "armor" || def.armorSlot !== armorSlot) continue;
303	    next[armorSlot] = equippedId;
304	  }
305	  return next;
306	}
307	
308	export function restoreSelectedSlot(save: SaveData): number | null {
309	  if (typeof save.selectedSlot !== "number") return null;
310	  return normalizeSelectedSlot(save.selectedSlot);
311	}
312	
313	/** Restores the day clock from a save (finite, non-negative); null if absent/invalid. */
314	export function restoreDayClock(save: SaveData): number | null {
315	  if (typeof save.dayClock !== "number" || !Number.isFinite(save.dayClock) || save.dayClock < 0) return null;
316	  return save.dayClock;
317	}
318	
319	/** Restores hearts clamped to 1..MAX_HEARTS; null if absent/invalid. */
320	export function restoreHearts(save: SaveData): number | null {
321	  if (typeof save.hearts !== "number" || !Number.isFinite(save.hearts)) return null;
322	  return Math.max(1, Math.min(MAX_HEARTS, Math.floor(save.hearts)));
323	}
324	
325	/** Restores hunger clamped to 0..MAX_HUNGER; null if absent/invalid. */
326	export function restoreHungerLevel(save: SaveData): number | null {
327	  if (typeof save.hunger !== "number" || !Number.isFinite(save.hunger)) return null;
328	  return Math.max(0, Math.min(MAX_HUNGER, Math.floor(save.hunger)));
329	}
330	
331	/** Restores banked XP (finite, ≥ 0); 0 when absent or invalid. */
332	export function restoreXp(save: SaveData): number {
333	  if (typeof save.xp !== "number" || !Number.isFinite(save.xp) || save.xp < 0) return 0;
334	  return Math.floor(save.xp);
335	}
336	
337	/** Restores the saved game mode; "survival" when absent or invalid (pre-v8 saves). */
338	export function restoreGameMode(save: SaveData): GameMode {
339	  return isGameMode(save.gameMode) ? save.gameMode : "survival";
340	}
341	
342	/** Restores the bed respawn point; null if absent or explicitly cleared. */
343	export function restoreSpawnPoint(save: SaveData): { x: number; y: number; z: number } | null {
344	  const sp = save.spawnPoint;
345	  if (!sp || !Number.isFinite(sp.x) || !Number.isFinite(sp.y) || !Number.isFinite(sp.z)) return null;
346	  return { x: Math.floor(sp.x), y: Math.floor(sp.y), z: Math.floor(sp.z) };
347	}
348	
349	/**
350	 * Restores the player's position; null when absent or non-finite. A corrupt save
351	 * with NaN/Infinity coords would otherwise load a broken world — and slip past the
352	 * `position.y < 2` unstuck net, since any comparison with NaN is false. Coords stay
353	 * floats (the player isn't grid-aligned), unlike the floored spawn point.
354	 */
355	export function restorePlayerPosition(save: SaveData): { x: number; y: number; z: number } | null {
356	  const p = save.player;
357	  if (!p || !Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) return null;
358	  return { x: p.x, y: p.y, z: p.z };
359	}
