1	/**
2	 * Worlds — the second level of the save hierarchy. Each world belongs to one
3	 * profile (`profileId`) and owns a single bundled SaveData blob under its own
4	 * `minecraft_world_save_<id>` key (read/written with the existing
5	 * lib/game/save.ts helpers). The world *index* — names, seeds, ordering — lives
6	 * in one versioned manifest blob; the heavy per-world saves stay separate so
7	 * the index reads cheaply.
8	 *
9	 * A world's `seed` is resolved once at creation and is the source of truth for
10	 * regeneration; `worldgenVersion` records the WORLDGEN_VERSION it was generated
11	 * under so a future baseline bump can discard its stale block-diffs.
12	 */
13	
14	import { isWorldType, type WorldType } from "@/lib/world";
15	import { isGameMode, type GameMode } from "./gameModes";
16	import { WORLDGEN_VERSION } from "./config";
17	import { readManifestRaw, resolveDeps, sanitizeName, writeManifest, type ManifestDeps } from "./manifest";
18	import { getProfile } from "./profiles";
19	
20	export type WorldMeta = {
21	  id: string;
22	  profileId: string;
23	  name: string;
24	  seed: number;
25	  worldType: WorldType;
26	  /** Initial game mode, chosen at creation. The *current* mode (switchable in-game) lives in the save blob. */
27	  gameMode: GameMode;
28	  worldgenVersion: number;
29	  createdAt: number;
30	  lastPlayedAt: number;
31	};
32	
33	/** UI metadata for the world-type picker (the engine side lives in lib/world/worldTypes.ts). */
34	export const WORLD_TYPE_PRESETS: ReadonlyArray<{ id: WorldType; label: string; blurb: string }> = [
35	  { id: "default", label: "Default", blurb: "Balanced terrain, every biome" },
36	  { id: "flat", label: "Superflat", blurb: "Level ground — a builder's canvas" },
37	  { id: "amplified", label: "Amplified", blurb: "Towering, dramatic relief" },
38	  { id: "islands", label: "Islands", blurb: "Scattered land in a wide sea" }
39	];
40	
41	export type WorldsManifest = {
42	  version: 1;
43	  worlds: WorldMeta[];
44	};
45	
46	export const WORLDS_KEY = "minecraft_worlds_v1";
47	export const WORLD_SAVE_PREFIX = "minecraft_world_save_";
48	export const MAX_WORLD_NAME = 32;
49	export const DEFAULT_WORLD_NAME = "New World";
50	export const MAX_SEED = 2147483647;
51	
52	export const DEFAULT_WORLDS_MANIFEST: WorldsManifest = { version: 1, worlds: [] };
53	
54	/** The per-world SaveData key handed to readSave/writeSave. */
55	export function worldSaveKey(worldId: string): string {
56	  return WORLD_SAVE_PREFIX + worldId;
57	}
58	
59	/** FNV-1a hash of a text seed into a stable non-negative 31-bit integer (Minecraft-style). */
60	export function hashStringToSeed(text: string): number {
61	  let hash = 0x811c9dc5;
62	  for (let i = 0; i < text.length; i += 1) {
63	    hash ^= text.charCodeAt(i);
64	    hash = Math.imul(hash, 0x01000193);
65	  }
66	  return Math.abs(hash | 0) % MAX_SEED;
67	}
68	
69	/**
70	 * Resolves a user seed input to an integer in 0..MAX_SEED-1: blank → random
71	 * (same entropy the engine used for a fresh world), numeric text → clamped int,
72	 * any other text → stable hash. `rng` is injectable for deterministic tests.
73	 */
74	export function resolveSeed(seedInput: string | null, rng: () => number = Math.random): number {
75	  const trimmed = (seedInput ?? "").trim();
76	  if (trimmed === "") return Math.floor(rng() * MAX_SEED);
77	  const asNumber = Number(trimmed);
78	  if (Number.isFinite(asNumber)) return Math.floor(Math.abs(asNumber)) % MAX_SEED;
79	  return hashStringToSeed(trimmed);
80	}
81	
82	/** Coerces one raw entry into a valid WorldMeta, or null if it can't be salvaged. */
83	function sanitizeWorld(raw: unknown): WorldMeta | null {
84	  if (!raw || typeof raw !== "object") return null;
85	  const entry = raw as Record<string, unknown>;
86	  if (typeof entry.id !== "string" || entry.id.length === 0) return null;
87	  if (typeof entry.profileId !== "string" || entry.profileId.length === 0) return null;
88	  if (typeof entry.seed !== "number" || !Number.isFinite(entry.seed)) return null;
89	  const num = (value: unknown, fallback: number) => (typeof value === "number" && Number.isFinite(value) ? value : fallback);
90	  return {
91	    id: entry.id,
92	    profileId: entry.profileId,
93	    name: sanitizeName(entry.name, DEFAULT_WORLD_NAME, MAX_WORLD_NAME),
94	    seed: Math.floor(entry.seed),
95	    worldType: isWorldType(entry.worldType) ? entry.worldType : "default",
96	    gameMode: isGameMode(entry.gameMode) ? entry.gameMode : "survival",
97	    worldgenVersion: num(entry.worldgenVersion, WORLDGEN_VERSION),
98	    createdAt: num(entry.createdAt, 0),
99	    lastPlayedAt: num(entry.lastPlayedAt, 0)
100	  };
101	}
102	
103	/** Reads the worlds manifest, dropping malformed entries. Never throws. */
104	export function readWorlds(storage: Storage = localStorage): WorldsManifest {
105	  const raw = readManifestRaw(WORLDS_KEY, storage) as Partial<WorldsManifest> | null;
106	  // Only the current manifest version is understood; an unknown version falls
107	  // back to the default rather than risk misreading an incompatible payload.
108	  if (!raw || raw.version !== 1 || !Array.isArray(raw.worlds)) return { ...DEFAULT_WORLDS_MANIFEST };
109	  return { version: 1, worlds: raw.worlds.map(sanitizeWorld).filter((w): w is WorldMeta => w !== null) };
110	}
111	
112	export function getWorld(id: string, storage: Storage = localStorage): WorldMeta | null {
113	  return readWorlds(storage).worlds.find((w) => w.id === id) ?? null;
114	}
115	
116	/** A profile's worlds, most-recently-played first (ties broken by creation time). */
117	export function worldsForProfile(profileId: string, storage: Storage = localStorage): WorldMeta[] {
118	  return readWorlds(storage)
119	    .worlds.filter((w) => w.profileId === profileId)
120	    .sort((a, b) => b.lastPlayedAt - a.lastPlayedAt || b.createdAt - a.createdAt);
121	}
122	
123	/** Creates a world for an existing profile, persists it, and returns it (throws on an unknown profile). `deps.rng` seeds blank-input worlds; `deps.worldType` picks the generation preset; `deps.gameMode` picks the initial game mode. */
124	export function createWorld(
125	  profileId: string,
126	  name: string,
127	  seedInput: string | null,
128	  deps: ManifestDeps & { rng?: () => number; worldType?: WorldType; gameMode?: GameMode } = {}
129	): WorldMeta {
130	  const { storage, now, uid } = resolveDeps(deps);
131	  // Worlds must belong to a real profile — refuse to persist an orphan record.
132	  if (!getProfile(profileId, storage)) throw new Error(`createWorld: unknown profile "${profileId}"`);
133	  const createdAt = now();
134	  const world: WorldMeta = {
135	    id: uid(),
136	    profileId,
137	    name: sanitizeName(name, DEFAULT_WORLD_NAME, MAX_WORLD_NAME),
138	    seed: resolveSeed(seedInput, deps.rng ?? Math.random),
139	    worldType: isWorldType(deps.worldType) ? deps.worldType : "default",
140	    gameMode: isGameMode(deps.gameMode) ? deps.gameMode : "survival",
141	    worldgenVersion: WORLDGEN_VERSION,
142	    createdAt,
143	    lastPlayedAt: createdAt
144	  };
145	  const manifest = readWorlds(storage);
146	  writeManifest(WORLDS_KEY, { version: 1, worlds: [...manifest.worlds, world] }, storage);
147	  return world;
148	}
149	
150	export function renameWorld(id: string, name: string, storage: Storage = localStorage): WorldsManifest {
151	  const manifest = readWorlds(storage);
152	  const next: WorldsManifest = {
153	    version: 1,
154	    worlds: manifest.worlds.map((w) => (w.id === id ? { ...w, name: sanitizeName(name, w.name, MAX_WORLD_NAME) } : w))
155	  };
156	  writeManifest(WORLDS_KEY, next, storage);
157	  return next;
158	}
159	
160	/** Bumps a world's `lastPlayedAt` so it sorts to the top of its profile's list. */
161	export function touchWorld(id: string, deps: ManifestDeps = {}): WorldsManifest {
162	  const { storage, now } = resolveDeps(deps);
163	  const manifest = readWorlds(storage);
164	  const next: WorldsManifest = {
165	    version: 1,
166	    worlds: manifest.worlds.map((w) => (w.id === id ? { ...w, lastPlayedAt: now() } : w))
167	  };
168	  writeManifest(WORLDS_KEY, next, storage);
169	  return next;
170	}
171	
172	/** Removes a world from the index and deletes its save blob. */
173	export function deleteWorld(id: string, storage: Storage = localStorage): WorldsManifest {
174	  const manifest = readWorlds(storage);
175	  const next: WorldsManifest = { version: 1, worlds: manifest.worlds.filter((w) => w.id !== id) };
176	  writeManifest(WORLDS_KEY, next, storage);
177	  try {
178	    storage.removeItem(worldSaveKey(id));
179	  } catch {
180	    // A failed blob cleanup just leaves an orphaned key; the index no longer references it.
181	  }
182	  return next;
183	}
184	
185	/** Cascade for profile deletion: removes every world of a profile and its save blobs. */
186	export function deleteWorldsForProfile(profileId: string, storage: Storage = localStorage): WorldsManifest {
187	  const manifest = readWorlds(storage);
188	  const doomed = manifest.worlds.filter((w) => w.profileId === profileId);
189	  const next: WorldsManifest = { version: 1, worlds: manifest.worlds.filter((w) => w.profileId !== profileId) };
190	  writeManifest(WORLDS_KEY, next, storage);
191	  for (const world of doomed) {
192	    try {
193	      storage.removeItem(worldSaveKey(world.id));
194	    } catch {
195	      // Orphaned blob; the index no longer references it.
196	    }
197	  }
198	  return next;
199	}
